  "shell.helpSessionTitle": "会话模式教程",
  "shell.helpBatchTitle": "批量模式教程",
  "drawer.batchModeHint": "在批量工作区创建并管理列表。",
  "shell.helpSessionBody":
    "会话模式围绕单个视频组织工作：\n1. 绑定当前页或输入 BV 地址创建会话。\n2. 获取字幕后在时间轴、对话、分段和总结四个工作区查看。\n3. 会话数据与批量列表完全隔离；归档与回收站按会话单独管理。\n危险操作（删除、清空）都会先确认。\n语音转录的语言设置只能促进识别，不能保证最终字幕语言，也不会把字幕翻译为所选语言。",
  "shell.helpBatchBody":
    "批量模式以长期列表组织多个视频：\n1. 先新建列表，再向当前列表追加来源；同一视频按精确身份去重。\n2. 当前列表全部视频直接显示，用顶部筛选定位；批量获取字幕统一在对话框中选择方法。\n3. 列表可重命名、置顶、归档或删除；删除进入批量回收站，恢复后不会自动续跑。\n批量数据与会话数据完全隔离；批量任务独立于会话，不会创建或修改会话。\n批量任务需要使用当前浏览器登录 Bilibili 的凭据（仅在用户操作期间、仅用于 Bilibili 第一方请求）；凭据不会显示、复制或导出。\n语言设置只能促进识别，不能保证最终字幕语言，也不会把字幕翻译为所选语言。",
  "shell.helpSessionArchiveTitle": "会话归档教程",
  "shell.helpSessionArchiveBody":
    "归档区保存暂时不用的会话：\n1. 用顶部搜索按标题或 BV 号查找会话。\n2. 多选后批量恢复，或批量移入回收站；恢复的会话回到工作区并保留全部内容。\n3. 三点菜单可对单个会话执行同样操作。\n归档中的会话不会自动路由或参与新建会话。",
  "shell.helpSessionTrashTitle": "会话回收站教程",
  "shell.helpSessionTrashBody":
    "回收站保存已删除的会话：\n1. 搜索、多选、恢复与归档区一致；恢复立即回到工作区。\n2. 永久删除会清除会话、字幕、对话与全部派生数据，无法恢复。\n3. 危险操作都需要确认，删除会话不会影响其它会话。",
  "shell.helpBatchArchiveTitle": "批量归档教程",
  "shell.helpBatchArchiveBody":
    "批量归档保存暂时不用的列表：\n1. 搜索只过滤列表名称，不影响右侧视频筛选。\n2. 多选后批量恢复，或批量移入批量回收站；恢复的列表回到工作区并保留全部视频与字幕。\n3. 三点菜单可对单个列表执行同样操作。\n批量归档与会话归档完全隔离。",
  "shell.helpBatchTrashTitle": "批量回收站教程",
  "shell.helpBatchTrashBody":
    "批量回收站保存已删除的列表：\n1. 搜索、多选、恢复与归档区一致；恢复立即回到工作区。\n2. 永久删除会清理列表的来源历史、字幕与操作进度，无法恢复。\n3. 危险操作都需要确认；批量数据与会话数据完全隔离，删除列表不会影响任何会话。",
