  "drawer.batchModeHint": "在批量工作區建立並管理列表。",
  "shell.helpSessionBody":
    "會話模式圍繞單一影片組織工作：\n1. 綁定目前頁面或輸入 BV 位址建立會話。\n2. 取得字幕後在時間軸、對話、分段和總結四個工作區查看。\n3. 會話資料與批量列表完全隔離；封存與回收筒按會話單獨管理。\n危險操作（刪除、清空）都會先確認。\n語音轉錄的語言設定只能促進辨識，無法保證最終字幕語言，也不會把字幕翻譯成所選語言。",
  "shell.helpBatchBody":
    "批量模式以長期列表組織多個影片：\n1. 先建立列表，再向目前列表追加來源；同一影片依精確身分去重。\n2. 目前列表全部影片直接顯示，用頂端篩選定位；批次取得字幕統一在對話框中選擇方法。\n3. 列表可重新命名、置頂、封存或刪除；刪除進入批次回收站，復原後不會自動續跑。\n批次資料與會話資料完全隔離；批次任務獨立於會話，不會建立或修改會話。\n批次任務需要使用目前瀏覽器登入 Bilibili 的憑據（僅在使用者操作期間、僅用於 Bilibili 第一方請求）；憑據不會顯示、複製或匯出。\n語言設定只能促進辨識，不能保證最終字幕語言，也不會把字幕翻譯為所選語言。",
  "shell.helpSessionArchiveTitle": "會話封存教學",
  "shell.helpSessionArchiveBody":
    "封存區保存暫時不用的會話：\n1. 用頂端搜尋依標題或 BV 號查詢會話。\n2. 多選後批次復原，或批次移入資源回收筒；復原的會話回到工作區並保留全部內容。\n3. 三點選單可對單一會話執行同樣操作。\n封存中的會話不會自動路由或參與新建會話。",
  "shell.helpSessionTrashTitle": "會話資源回收筒教學",
  "shell.helpSessionTrashBody":
    "資源回收筒保存已刪除的會話：\n1. 搜尋、多選、復原與封存區一致；復原立即回到工作區。\n2. 永久刪除會清除會話、字幕、對話與全部衍生資料，無法復原。\n3. 危險操作都需要確認，刪除會話不會影響其它會話。",
  "shell.helpBatchArchiveTitle": "批次封存教學",
  "shell.helpBatchArchiveBody":
    "批次封存保存暫時不用的列表：\n1. 搜尋只過濾列表名稱，不影響右側影片篩選。\n2. 多選後批次復原，或批次移入批次資源回收筒；復原的列表回到工作區並保留全部影片與字幕。\n3. 三點選單可對單一列表執行同樣操作。\n批次封存與會話封存完全隔離。",
  "shell.helpBatchTrashTitle": "批次資源回收筒教學",
