  "shell.helpSessionTitle": "Session mode help",
  "shell.helpBatchTitle": "Batch mode help",
  "drawer.batchModeHint": "Create and manage lists in the batch workspace.",
  "shell.helpSessionBody":
    "Session mode organizes work around one video:\n1. Bind the current page or enter a BV address to create a session.\n2. After fetching subtitles, use the Timeline, Chat, Segments and Summary workspaces.\n3. Session data is fully isolated from batch lists; archive and trash are managed per mode.\nDestructive actions always ask for confirmation first.\nSpeech transcription language settings only help recognition; they cannot guarantee the final subtitle language or translate subtitles into the selected language.",
  "shell.helpBatchBody":
    "Batch mode organizes multiple videos into persistent lists:\n1. Create a list first, then append sources to it; the same video is deduplicated by exact identity.\n2. All videos in the current list are shown directly; use the top filter to find them, and choose the acquisition method in one dialog.\n3. Lists can be renamed, pinned, archived, or deleted; deleted lists go to the batch trash and will not auto-resume after restore.\nBatch data is fully isolated from sessions; batch tasks never create or modify sessions.\nBatch tasks use the current browser login for Bilibili (only during user actions and only for first-party Bilibili requests); credentials are never shown, copied, or exported.\nLanguage settings only help recognition; they never guarantee the final subtitle language, and subtitles are never translated into the chosen language.",
  "shell.helpSessionArchiveTitle": "Session archive guide",
  "shell.helpSessionArchiveBody":
    "The archive keeps sessions you are not using right now:\n1. Use the top search to find sessions by title or BV id.\n2. Multi-select to restore in bulk, or move to trash in bulk; restored sessions return to the workspace with all content intact.\n3. The three-dot menu offers the same actions for a single session.\nArchived sessions never auto-route or join session creation.",
  "shell.helpSessionTrashTitle": "Session trash guide",
  "shell.helpSessionTrashBody":
    "The trash keeps deleted sessions:\n1. Search, multi-select and restore work like the archive; restored sessions return to the workspace immediately.\n2. Permanent deletion clears the session, subtitles, chats and all derived data and cannot be undone.\n3. Destructive actions always ask for confirmation; deleting one session never affects others.",
  "shell.helpBatchArchiveTitle": "Batch archive guide",
  "shell.helpBatchArchiveBody":
    "Batch archive keeps lists you are not using right now:\n1. Search filters list names only and never affects the right-side video filter.\n2. Multi-select to restore in bulk, or move to the batch trash in bulk; restored lists return with all videos and subtitles.\n3. The three-dot menu offers the same actions for a single list.\nBatch archive is fully isolated from the session archive.",
  "shell.helpBatchTrashTitle": "Batch trash guide",
  "shell.helpBatchTrashBody":
    "The batch trash keeps deleted lists:\n1. Search, multi-select and restore work like the archive; restored lists return to the workspace immediately.\n2. Permanent deletion clears the list's source history, subtitles and operation progress and cannot be undone.\n3. Destructive actions always ask for confirmation; batch data is fully isolated from sessions, so deleting a list never affects any session.",
