  "header.returnToWorkspace": "ワークスペースに戻る",
  "header.helpAria": "現在のモードのヘルプを表示",
  "header.helpTitle": "現在のモードのヘルプ",
  "header.githubAria": "Bilimuzhiの GitHub リポジトリ",
  "header.githubStar": "気に入っていただけたらスターをお願いします",
  "shell.helpSessionTitle": "セッションモードのヘルプ",
  "shell.helpBatchTitle": "バッチモードのヘルプ",
  "drawer.batchModeHint": "リストはバッチワークスペースで作成・管理します。",
  "shell.helpSessionBody":
    "セッションモードは1本の動画を中心に作業します：\n1. 現在のページをバインドするか、BVアドレスを入力してセッションを作成。\n2. 字幕取得後、タイムライン・チャット・セグメント・サマリーの4つのワークスペースで確認。\n3. セッションのデータはバッチリストと完全に分離されています。アーカイブとゴミ箱はモードごとに管理されます。\n破壊的な操作は必ず確認されます。\n音声文字起こしの言語設定は認識を助けるだけであり、最終的な字幕言語を保証するものではなく、選択した言語に字幕を翻訳することもありません。",
  "shell.helpBatchBody":
    "バッチモードでは複数の動画を永続リストに整理します：\n1. 最初にリストを作成し、ソースを追加します。同一動画は正確な ID で重複排除されます。\n2. 現在のリストの全動画を直接表示します。上部のフィルターで位置を特定し、字幕取得はダイアログで方式を選択します。\n3. リストは名前変更・ピン留め・アーカイブ・削除が可能です。削除はバッチゴミ箱へ移動し、復元後も自動再開しません。\nバッチデータはセッションと完全に分離され、バッチタスクがセッションを作成・変更することはありません。\nバッチタスクは現在のブラウザの Bilibili ログインを使用します（ユーザー操作中のみ・Bilibili 第一者リクエストのみ）。認証情報は表示・コピー・書き出しされません。\n言語設定は認識を助けるだけであり、最終的な字幕言語を保証するものではなく、字幕が選択言語に翻訳されることもありません。",
  "shell.helpSessionArchiveTitle": "セッションアーカイブのヘルプ",
  "shell.helpSessionArchiveBody":
    "アーカイブには一時的に使わないセッションを保存します：\n1. 上部の検索でタイトルや BV 番号からセッションを探します。\n2. 複数選択で一括復元、または一括でゴミ箱へ移動できます。復元したセッションはワークスペースに戻り、内容はすべて保持されます。\n3. 三点メニューから単一セッションにも同じ操作ができます。\nアーカイブ中のセッションは自動ルーティングや新規作成には参加しません。",
  "shell.helpSessionTrashTitle": "セッションゴミ箱のヘルプ",
  "shell.helpSessionTrashBody":
    "ゴミ箱には削除したセッションが保存されます：\n1. 検索・複数選択・復元はアーカイブと同じです。復元するとすぐにワークスペースへ戻ります。\n2. 完全削除するとセッション・字幕・会話・派生データがすべて消え、元に戻せません。\n3. 危険な操作は必ず確認を求めます。あるセッションの削除が他のセッションに影響することはありません。",
  "shell.helpBatchArchiveTitle": "バッチアーカイブのヘルプ",
  "shell.helpBatchArchiveBody":
    "バッチアーカイブには一時的に使わないリストを保存します：\n1. 検索はリスト名のみを対象とし、右側の動画フィルターには影響しません。\n2. 複数選択で一括復元、または一括でバッチゴミ箱へ移動できます。復元したリストは動画・字幕ごと戻ります。\n3. 三点メニューから単一リストにも同じ操作ができます。\nバッチアーカイブはセッションアーカイブと完全に分離されています。",
  "shell.helpBatchTrashTitle": "バッチゴミ箱のヘルプ",
  "shell.helpBatchTrashBody":
    "バッチゴミ箱には削除したリストが保存されます：\n1. 検索・複数選択・復元はアーカイブと同じです。復元するとすぐにワークスペースへ戻ります。\n2. 完全削除するとリストのソース履歴・字幕・操作進行がすべて消え、元に戻せません。\n3. 危険な操作は必ず確認を求めます。バッチデータはセッションと完全に分離されており、リスト削除がセッションに影響することはありません。",
